-- ONLY for the disposable local Supabase database, AFTER the proposed SQL has run.
-- Data and audit generated by the test are rolled back. NEVER use on production.
begin;
create temp table _inclusion_proposal_checks (
  step text not null,
  expected text not null,
  actual text not null,
  ok boolean not null
) on commit drop;
grant all on _inclusion_proposal_checks to public;

create function pg_temp.run_as_inclusion(p_role text, p_sub uuid, p_query text)
returns text language plpgsql as $fn$
declare v_out text;
begin
  perform pg_catalog.set_config(
    'request.jwt.claims',
    case when p_sub is null then pg_catalog.json_build_object('role', p_role)::text
         else pg_catalog.json_build_object('role', p_role, 'sub', p_sub)::text end,
    true
  );
  execute pg_catalog.format('set local role %I', p_role);
  begin
    execute p_query into v_out;
  exception when others then
    v_out := pg_catalog.format('ERROR %s: %s', sqlstate, sqlerrm);
  end;
  reset role;
  perform pg_catalog.set_config('request.jwt.claims', '', true);
  return coalesce(v_out, '(null)');
end;
$fn$;

create function pg_temp.expect_inclusion(p_step text, p_expected text, p_actual text)
returns void language sql as $fn$
  insert into _inclusion_proposal_checks (step, expected, actual, ok)
  values (p_step, p_expected, p_actual, position(p_expected in p_actual) > 0);
$fn$;

set local session_replication_role = replica;

insert into auth.users (id, email, raw_user_meta_data) values
  ('00000000-0000-4000-8000-00000000f701', 'inclusion-admin@runtime.invalid', '{}'::jsonb),
  ('00000000-0000-4000-8000-00000000f702', 'inclusion-dealer@runtime.invalid', '{}'::jsonb),
  ('00000000-0000-4000-8000-00000000f703', 'inclusion-master@runtime.invalid', '{}'::jsonb);

insert into public.profiles (id, email, full_name, role_code) values
  ('00000000-0000-4000-8000-00000000f701', 'inclusion-admin@runtime.invalid', '設備包含テスト管理者', 'admin'),
  ('00000000-0000-4000-8000-00000000f702', 'inclusion-dealer@runtime.invalid', '設備包含テスト代理店', 'dealer'),
  ('00000000-0000-4000-8000-00000000f703', 'inclusion-master@runtime.invalid', '設備包含テスト総代理店', 'master_dealer');

insert into public.option_categories (id, code, name, group_code, group_name, status) values
  ('00000000-0000-4000-8000-00000000f710', 'ub', 'テスト浴室', 'equipment', '設備機器', 'published'),
  ('00000000-0000-4000-8000-00000000f711', 'toilet', 'テストトイレ', 'equipment', '設備機器', 'published'),
  ('00000000-0000-4000-8000-00000000f712', 'washbasin', 'テスト洗面', 'equipment', '設備機器', 'published'),
  ('00000000-0000-4000-8000-00000000f713', 'runtime-inclusion-draft', '非公開設備', 'equipment', '設備機器', 'draft'),
  ('00000000-0000-4000-8000-00000000f714', 'kitchen', 'テストキッチン（包含対象外）', 'equipment', '設備機器', 'published');

insert into public.options (id, category_id, code, name, status, product_no) values
  ('00000000-0000-4000-8000-00000000f720', '00000000-0000-4000-8000-00000000f710', 'runtime-inclusion-product', '検証3点ユニット', 'published', 'PRD-999981'),
  ('00000000-0000-4000-8000-00000000f721', '00000000-0000-4000-8000-00000000f710', 'runtime-inclusion-hidden-product', '検証シャワートイレユニット', 'draft', 'PRD-999982'),
  ('00000000-0000-4000-8000-00000000f722', '00000000-0000-4000-8000-00000000f711', 'runtime-inclusion-non-ub', '検証UB以外の商品', 'draft', 'PRD-999983');

set local session_replication_role = origin;

do $tests$
declare
  v_admin constant uuid := '00000000-0000-4000-8000-00000000f701';
  v_dealer constant uuid := '00000000-0000-4000-8000-00000000f702';
  v_master constant uuid := '00000000-0000-4000-8000-00000000f703';
  v_pub constant uuid := '00000000-0000-4000-8000-00000000f720';
  v_draft constant uuid := '00000000-0000-4000-8000-00000000f721';
  v_non_ub constant uuid := '00000000-0000-4000-8000-00000000f722';
  v_ub constant uuid := '00000000-0000-4000-8000-00000000f710';
  v_toilet constant uuid := '00000000-0000-4000-8000-00000000f711';
  v_wash constant uuid := '00000000-0000-4000-8000-00000000f712';
  v_draft_category constant uuid := '00000000-0000-4000-8000-00000000f713';
  v_kitchen constant uuid := '00000000-0000-4000-8000-00000000f714';
  v_call text;
  v_actual text;
begin
  v_call := pg_catalog.format(
    'select public.set_option_included_categories(%L::uuid, array[]::uuid[], array[%L::uuid,%L::uuid])::text',
    v_pub, v_toilet, v_wash
  );
  perform pg_temp.expect_inclusion(
    'anonymous RPC denied', 'ERROR 42501',
    pg_temp.run_as_inclusion('anon', null, v_call)
  );
  perform pg_temp.expect_inclusion(
    'dealer RPC forbidden', 'ERROR 42501',
    pg_temp.run_as_inclusion('authenticated', v_dealer, v_call)
  );
  perform pg_temp.expect_inclusion(
    'master_dealer RPC forbidden despite legacy can_edit_catalog rank2', 'ERROR 42501',
    pg_temp.run_as_inclusion('authenticated', v_master, v_call)
  );
  perform pg_temp.expect_inclusion(
    'admin stores categories', v_toilet::text,
    pg_temp.run_as_inclusion('authenticated', v_admin, v_call)
  );
  select count(*)::text into v_actual
    from public.option_included_categories where option_id = v_pub;
  perform pg_temp.expect_inclusion('two category links stored', '2', v_actual);

  perform pg_temp.expect_inclusion(
    'optimistic conflict rejects stale empty set', 'CONFLICT:',
    pg_temp.run_as_inclusion('authenticated', v_admin, v_call)
  );
  perform pg_temp.expect_inclusion(
    'self category rejected', 'VALIDATION:',
    pg_temp.run_as_inclusion('authenticated', v_admin, pg_catalog.format(
      'select public.set_option_included_categories(%L::uuid, array[%L::uuid,%L::uuid], array[%L::uuid])::text',
      v_pub, v_toilet, v_wash, v_ub
    ))
  );
  perform pg_temp.expect_inclusion(
    'unpublished new category rejected', 'VALIDATION:',
    pg_temp.run_as_inclusion('authenticated', v_admin, pg_catalog.format(
      'select public.set_option_included_categories(%L::uuid, array[%L::uuid,%L::uuid], array[%L::uuid,%L::uuid,%L::uuid])::text',
      v_pub, v_toilet, v_wash, v_toilet, v_wash, v_draft_category
    ))
  );
  select count(*)::text into v_actual
    from public.option_included_categories where option_id = v_pub;
  perform pg_temp.expect_inclusion('failed saves roll back relations', '2', v_actual);

  perform pg_temp.expect_inclusion(
    'anonymous cannot delete link directly', 'ERROR 42501',
    pg_temp.run_as_inclusion('anon', null, pg_catalog.format(
      'delete from public.option_included_categories where option_id = %L::uuid returning option_id::text', v_pub
    ))
  );
  perform pg_temp.expect_inclusion(
    'authenticated cannot delete link directly', 'ERROR 42501',
    pg_temp.run_as_inclusion('authenticated', v_admin, pg_catalog.format(
      'delete from public.option_included_categories where option_id = %L::uuid returning option_id::text', v_pub
    ))
  );
  perform pg_temp.expect_inclusion(
    'anon sees published source', '2',
    pg_temp.run_as_inclusion('anon', null, pg_catalog.format(
      'select count(*)::text from public.option_included_categories where option_id = %L::uuid', v_pub
    ))
  );

  perform pg_temp.expect_inclusion(
    'shower toilet unit selects only toilet', v_toilet::text,
    pg_temp.run_as_inclusion('authenticated', v_admin, pg_catalog.format(
      'select public.set_option_included_categories(%L::uuid, array[]::uuid[], array[%L::uuid])::text',
      v_draft, v_toilet
    ))
  );
  perform pg_temp.expect_inclusion(
    'anon cannot see draft source inclusion', '0',
    pg_temp.run_as_inclusion('anon', null, pg_catalog.format(
      'select count(*)::text from public.option_included_categories where option_id = %L::uuid', v_draft
    ))
  );
  perform pg_temp.expect_inclusion(
    'master_dealer cannot read draft source inclusion', '0',
    pg_temp.run_as_inclusion('authenticated', v_master, pg_catalog.format(
      'select count(*)::text from public.option_included_categories where option_id = %L::uuid', v_draft
    ))
  );
  -- Options category cannot be changed to a category that the product includes.
  begin
    update public.options set category_id = v_toilet where id = v_pub;
    v_actual := 'UPDATED';
  exception when others then
    v_actual := sqlstate;
  end;
  perform pg_temp.expect_inclusion('invariant blocks category update to included category', 'P0001', v_actual);
  select category_id::text into v_actual from public.options where id = v_pub;
  perform pg_temp.expect_inclusion('failed category update leaves original category', v_ub::text, v_actual);

  -- High-risk invalid inputs should reject before any data or audit changes.
  perform pg_temp.expect_inclusion(
    'null next category array rejected', 'VALIDATION:',
    pg_temp.run_as_inclusion('authenticated', v_admin, pg_catalog.format(
      'select public.set_option_included_categories(%L::uuid, array[%L::uuid,%L::uuid], null::uuid[])::text',
      v_pub, v_toilet, v_wash
    ))
  );
  perform pg_temp.expect_inclusion(
    'null element rejected', 'VALIDATION:',
    pg_temp.run_as_inclusion('authenticated', v_admin, pg_catalog.format(
      'select public.set_option_included_categories(%L::uuid, array[%L::uuid,%L::uuid], array[null::uuid])::text',
      v_pub, v_toilet, v_wash
    ))
  );
  perform pg_temp.expect_inclusion(
    'duplicate category rejected', 'VALIDATION:',
    pg_temp.run_as_inclusion('authenticated', v_admin, pg_catalog.format(
      'select public.set_option_included_categories(%L::uuid, array[%L::uuid,%L::uuid], array[%L::uuid,%L::uuid])::text',
      v_pub, v_toilet, v_wash, v_toilet, v_toilet
    ))
  );
  perform pg_temp.expect_inclusion(
    'unknown category UUID rejected', 'VALIDATION:',
    pg_temp.run_as_inclusion('authenticated', v_admin, pg_catalog.format(
      'select public.set_option_included_categories(%L::uuid, array[%L::uuid,%L::uuid], array[%L::uuid])::text',
      v_pub, v_toilet, v_wash, '00000000-0000-4000-8000-00000000f799'
    ))
  );
  perform pg_temp.expect_inclusion(
    'service_role cannot call inclusion RPC', 'ERROR 42501',
    pg_temp.run_as_inclusion('service_role', null, v_call)
  );
  perform pg_temp.expect_inclusion(
    'unchanged set accepted', v_toilet::text,
    pg_temp.run_as_inclusion('authenticated', v_admin, pg_catalog.format(
      'select public.set_option_included_categories(%L::uuid, array[%L::uuid,%L::uuid], array[%L::uuid,%L::uuid])::text',
      v_pub, v_toilet, v_wash, v_toilet, v_wash
    ))
  );
  select count(*)::text into v_actual
    from public.audit_logs
   where entity_id in (v_pub, v_draft)
     and action = 'option.included_categories.save';
  perform pg_temp.expect_inclusion('unchanged save did not add audit', '2', v_actual);

  -- Guarded deletion behavior is tested after audit and all input tests.
  -- Prevent destructive deletion of an included *category* (never cascade to other product data).
  -- Test in nested exception subtransactions: no parent row may be deleted.
  perform pg_temp.expect_inclusion(
    'non-ub product cannot store included fixtures', 'VALIDATION:',
    pg_temp.run_as_inclusion('authenticated', v_admin, pg_catalog.format(
      'select public.set_option_included_categories(%L::uuid, array[]::uuid[], array[%L::uuid])::text',
      v_non_ub, v_toilet
    ))
  );
  perform pg_temp.expect_inclusion(
    'kitchen cannot be an included category', 'VALIDATION:',
    pg_temp.run_as_inclusion('authenticated', v_admin, pg_catalog.format(
      'select public.set_option_included_categories(%L::uuid, array[%L::uuid,%L::uuid], array[%L::uuid])::text',
      v_pub, v_toilet, v_wash, v_kitchen
    ))
  );
  select count(*)::text into v_actual
    from public.option_included_categories where option_id = v_pub;
  perform pg_temp.expect_inclusion('3-point UB retains own two included categories', '2', v_actual);
  select count(*)::text into v_actual
    from public.option_included_categories where option_id = v_draft;
  perform pg_temp.expect_inclusion('shower toilet unit has toilet but no washbasin', '1', v_actual);

  -- Any product category change while relations exist is prohibited, including
  -- a move to unrelated 'kitchen' (not just direct self-inclusion).
  begin
    update public.options set category_id = v_kitchen where id = v_draft;
    v_actual := 'UPDATED';
  exception when others then
    v_actual := sqlstate;
  end;
  perform pg_temp.expect_inclusion('non-self category change blocked while links exist', 'P0001', v_actual);

  begin
    delete from public.option_categories where id = v_wash;
    v_actual := 'DELETED';
  exception when others then
    v_actual := sqlstate;
  end;
  perform pg_temp.expect_inclusion('FK blocks deleting included category', '23503', v_actual);

  select count(*)::text into v_actual
    from public.audit_logs
   where entity_id in (v_pub, v_draft)
     and action = 'option.included_categories.save';
  perform pg_temp.expect_inclusion('audit records only successful changes', '2', v_actual);
  -- Published option uses the existing guarded safe-delete RPC. Its links may
  -- cascade only after BEFORE DELETE guard succeeds in the same transaction.
  perform pg_temp.expect_inclusion(
    'unused published UB deletes through safe-delete RPC', 'ok',
    pg_temp.run_as_inclusion('authenticated', v_admin, pg_catalog.format(
      $select 'ok' from (select public.delete_unused_published_option(%L::uuid)) deleted$,
      v_pub
    ))
  );
  select count(*)::text into v_actual from public.options where id = v_pub;
  perform pg_temp.expect_inclusion('published source removed', '0', v_actual);
  select count(*)::text into v_actual from public.option_included_categories where option_id = v_pub;
  perform pg_temp.expect_inclusion('published inclusion links cascaded atomically', '0', v_actual);

  -- Draft option uses the existing direct-delete path (RLS + BEFORE DELETE guard).
  perform pg_temp.expect_inclusion(
    'unused draft UB deletes through normal DELETE', 'ok',
    pg_temp.run_as_inclusion('authenticated', v_admin, pg_catalog.format(
      $with deleted as (delete from public.options where id = %L::uuid returning id) select case when count(*)=1 then 'ok' else 'missing' end from deleted$,
      v_draft
    ))
  );
  select count(*)::text into v_actual from public.options where id = v_draft;
  perform pg_temp.expect_inclusion('draft source removed', '0', v_actual);
  select count(*)::text into v_actual from public.option_included_categories where option_id = v_draft;
  perform pg_temp.expect_inclusion('draft inclusion links cascaded atomically', '0', v_actual);
end;
$tests$;

select coalesce(pg_catalog.jsonb_agg(
  pg_catalog.jsonb_build_object(
    'step', step, 'expected', expected, 'actual', actual, 'ok', ok
  ) order by step
), '[]'::jsonb) as checks from _inclusion_proposal_checks;
rollback;
